Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_refDataAreaId">DataArea to change to</param>
/// <returns>CompanyImage</returns>
public static CompanyImage avaGetCompanyImage(CompanyId _companyId = curExt())
{
    CompanyInfo avaCompanyInfo;
    CompanyImage avaCompanyImage;

    changecompany(_companyId)
    {
        avaCompanyInfo = CompanyInfo::find();
        avaCompanyImage = CompanyImage::find(avaCompanyInfo.DataAreaId, avaCompanyInfo.TableId, avaCompanyInfo.RecId);
    }

    return avaCompanyImage;
}
